#!/bin/bash
# sbatch_install_v6.sh — deploys extraction.sbatch to Emory login node
# Safe to re-run; overwrites target and verifies md5.
set -euo pipefail

TARGET="${HOME}/THYROID_2026/runbook/extraction.sbatch"
EXPECT_MD5="e07208710d7c90e1d5c1bd56db761929"

mkdir -p "$(dirname "$TARGET")"
# Back up the previous (broken) copy if it exists
if [ -f "$TARGET" ]; then
    cp -f "$TARGET" "${TARGET}.bak.$(date +%Y%m%d_%H%M%S)"
fi

# Write new sbatch from embedded base64
base64 -d > "$TARGET" <<'B64_EOF'

B64_EOF

ACTUAL_MD5=$(md5sum "$TARGET" | awk '{print $1}')
if [ "$ACTUAL_MD5" = "$EXPECT_MD5" ]; then
    echo "OK — md5 matches ($ACTUAL_MD5)"
    echo "   installed at: $TARGET"
    echo "   size:         $(wc -c < "$TARGET") bytes"
else
    echo "FAIL — md5 mismatch"
    echo "   expected: $EXPECT_MD5"
    echo "   actual:   $ACTUAL_MD5"
    exit 1
fi

# Also ensure apply_patches.py is present (unchanged from v5)
if [ ! -f "${HOME}/THYROID_2026/runbook/apply_patches.py" ]; then
    echo "WARN: apply_patches.py missing from ${HOME}/THYROID_2026/runbook/"
    echo "      Phase 3 will fail. Re-run the v5 installer if needed, or fetch manually."
fi

echo ""
echo "Next step:"
echo "   sbatch $TARGET"
